  border.color: root.pillBorderFor(slot.pillGroup)
  opacity: slot.dragSource ? 0.35 : 1.0

  // Both follow the theme, so both crossfade with it.
  Behavior on color {
    enabled: root.foregroundAnimationEnabled
    ColorAnimation { duration: 420; easing.type: Easing.InOutCubic }
  }

  Behavior on border.color {
    enabled: root.foregroundAnimationEnabled
    ColorAnimation { duration: 420; easing.type: Easing.InOutCubic }
  }
}

