function toggleTransparency() {
  // Pills keep the live request off whatever the file says, so the flip
  // has to read the file's value -- and leave pills, or nothing visible
  // would change: the strip is already clear because of them.
  var nextTransparent = !(root.pills ? root.configTransparent : root.requestedTransparent === true)
  var leavePills = root.pills
  if (root.shell && typeof root.shell.mutateShellConfig === "function") {
    root.shell.mutateShellConfig(function(config) {
      if (!Util.isPlainObject(config.bar)) config.bar = {}
      config.bar.transparent = nextTransparent
      if (leavePills) config.bar.pills = false
    })
  } else {
    if (leavePills) root.pills = false
    root.setRequestedTransparency(nextTransparent)
  }
}
